ims.com","entries":[{"type":"search_result","url":"https://www.earthsims.com/digital-nomad-tools/best-usb-c-chargers-travel/","title":"Best USB-C Travel Chargers 2026 | Earth SIMs","snippet":"","ref_id":{"turn_index":215474,"ref_type":"search","ref_index":5},"pub_date":1772496000.0,"result_type":"web","source_name":"Earth SIMs","attribution":"www.earthsims.com"}]},{"type":"search_result_group","domain":"techfromalex.com","entries":[{"type":"search_result","url":"https://techfromalex.com/travel-tech-kit-three-budgets","title":"Travel Tech Kit at Three Budgets (2026) | Tech From Alex","snippet":"","ref_id":{"turn_index":215474,"ref_type":"search","ref_index":6},"pub_date":1789603200.0,"result_type":"web","source_name":"Tech From Alex","attribution":"techfromalex.com"}]},{"type":"search_result_group","domain":"www.travelandleisure.com","entries":[{"type":"search_result","url":"https://www.travelandleisure.com/travel-tips/travel-trends/best-portable-power-banks","title":"The 12 Best Portable Chargers of 2026, Tested and Reviewed","snippet":"","ref_id":{"turn_index":215474,"ref_type":"search","ref_index":7},"pub_date":null,"result_type":"web","source_name":"Travel + Leisure","attribution":"www.travelandleisure.com"}]},{"type":"search_result_group","domain":"devicejoy.com","entries":[{"type":"search_result","url":"https://devicejoy.com/guides/best-travel-tech-essentials-2026/","title":"Best Travel Tech Essentials for 2026 (Carry-On Picks)","snippet":"","ref_id":{"turn_index":215474,"ref_type":"search","ref_index":8},"pub_date":1780790400.0,"result_type":"web","source_name":"DeviceJoy","attribution":"devicejoy.com"}]},{"type":"search_result_group","domain":"publicasta.com","entries":[{"type":"search_result","url":"https://publicasta.com/gadgets/travel_charging_kit_usb_c_2026_07_01?lang=en","title":"USB-C travel charging kit: what to pack in 2026","snippet":"","ref_id":{"turn_index":215474,"ref_type":"search","ref_index":9},"pub_date":1782864000.0,"result_type":"web","sourc